olid var(--line);min-width:0}.row>*{min-width:0;overflow-wrap:anywhere}.row small{display:block;color:var(--muted);margin-top:4px}.badge{border:1px solid #999;padding:5px 7px;font-size:10px;white-space:normal;overflow-wrap:anywhere;height:max-content;letter-spacing:.06em}.good{color:var(--good);border-color:var(--good)}.warn{color:var(--warn);border-color:var(--warn)}.alert{padding:11px 0;border-bottom:1px solid var(--line)}.alert strong{display:block}.alert span{display:block;color:var(--muted);font-size:13px;margin-top:4px}.actions{display:grid;gap:8px}.action{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid var(--line);background:#fff;padding:11px}.action button{min-height:38px}.permission{color:var(--muted);font-size:12px;line-height:1.5;margin-top:12px}.feedback{display:none;border:1px solid var(--good);color:var(--good);background:var(--accent-soft);padding:11px;margin-top:10px}.table{width:100%;max-width:100%;border-collapse:collapse;display:block;overflow-x:auto}.table th,.table td{text-align:left;border-bottom:1px solid var(--line);padding:10px 7px}.table th{font-size:10px;letter-spacing:.08em;text-transform:uppercase}.empty{border:1px dashed #aaa;padding:18px;color:var(--muted)}.wire{border:1px dashed #aaa;background:#fff;padding:18px;color:var(--muted)}.footer{border-top:1px solid var(--line);margin-top:28px;padding:18px 28px;display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;color:var(--muted);font-size:11px}.footer strong{color:var(--ink);letter-spacing:.08em}.footer-developers{margin-top:6px;color:var(--accent);font-size:10px;letter-spacing:.08em;text-transform:uppercase}.footer-links{display:flex;gap:14px;flex-wrap:wrap;align-items:center}.footer a{color:var(--accent);text-decoration:none}.footer a:hover,.footer a:focus{text-decoration:underline}input,select,textarea{max-width:100%;width:100%}.button:focus-visible,.link:focus-visible,.search:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:1200px){.resource-strip{grid-template-columns:repeat(4,1fr)}.wide,.side-card{grid-column:span 12}}@media(max-width:1050px){.resource-strip{grid-template-columns:repeat(3,1fr)}.wide,.side-card{grid-column:span 12}}@media(max-width:760px){.shell{grid-template-columns:1fr}.side{position:relative;height:auto;max-height:430px;border-right:0;border-bottom:1px solid var(--line)}.top,.content{padding:18px}.resources{width:100%;display:grid;grid-template-columns:repeat(2,1fr)}.resource{min-width:0}.metric-grid{grid-template-columns:1fr}.resource-strip{grid-template-columns:repeat(2,1fr)}.button{width:100%}.action{align-items:stretch;flex-direction:column}}
.account-menu{position:relative;display:flex;align-items:center;margin-left:8px}.account-menu-toggle{border:1px solid rgba(0,196,220,.45);background:#fff;color:#111;min-height:38px;padding:8px 12px;cursor:pointer;font:inherit;font-weight:700;display:flex;gap:8px;align-items:center}.account-menu-toggle:hover,.account-menu-toggle:focus{border-color:#00b8d4;outline:2px solid rgba(0,184,212,.18);outline-offset:2px}.account-panel{display:none;position:absolute;right:0;top:calc(100% + 8px);z-index:30;width:290px;background:#fff;border:1px solid #111;box-shadow:0 12px 30px rgba(0,0,0,.16);padding:14px}.account-panel.open{display:block}.account-panel h3{margin:0 0 4px;font-size:15px}.account-panel p{margin:0 0 12px;color:#5b6670;font-size:12px}.account-panel .account-action{display:flex;width:100%;justify-content:space-between;align-items:center;border:0;border-top:1px solid #e4eaee;background:#fff;color:#111;padding:10px 0;text-align:left;cursor:pointer;font:inherit}.account-panel .account-action:hover{color:#007f95}.account-panel label{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e4eaee;padding:10px 0;font-size:12px;color:#35414a}.account-panel select{width:116px;padding:5px;border:1px solid #b9c6cc;background:#fff}.account-panel .account-danger{color:#a11b2b}.account-panel .account-meta{font-size:11px;color:#6d7880;margin-top:10px}.account-panel input[type=checkbox]{accent-color:#00a9c2}@media(max-width:900px){.account-menu{margin-left:0}.account-panel{position:fixed;right:12px;top:76px;width:min(290px,calc(100vw - 24px))}}html[data-density=compact] .top{padding-top:7px;padding-bottom:7px}html[data-density=compact] .content{padding-top:16px}html[data-density=compact] .card{padding:10px}html[data-density=compact] .resource{padding:4px 6px}html[data-reduced-motion=true] *,html[data-reduced-motion=true] *::before,html[data-reduced-motion=true] *::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}@media(max-width:620px){.account-menu-toggle{padding:8px 9px}.account-menu-toggle .account-label{display:none}.account-panel{top:64px}.top{align-items:flex-start}.resources{width:100%}}</style></head><body><div class="shell"><aside class="side"><div class="brand">UNIVERSE CIVILIZATION: EMPIRE AT WARS / COMMAND CENTER</div><input id="search" class="search" placeholder="Search pages, actions, tables…" aria-label="Search pages"><nav id="nav"></nav></aside><main class="main"><header class="top"><div class="identity"><span><small>Commander</small><strong>Tanang</strong></span><span><small>Race</small><strong>Tau'ri</strong></span><span><small>Rank</small><strong>Commander</strong></span></div><div class="resources" aria-label="Strategic resources"><div class="resource resource-metal"><em>M</em><span><small>Metal</small><strong><?=number_format((int)($liveResources['metal'] ?? 0))?></strong></span></div><div class="resource resource-crystal"><em>C</em><span><small>Crystal</small><strong><?=number_format((int)($liveResources['crystal'] ?? 0))?></strong></span></div><div class="resource resource-naquadah"><em>N</em><span><small>Naquadah</small><strong><?=number_format((int)($liveResources['naquadah'] ?? 0))?></strong></span></div><div class="resource resource-energy"><em>E</em><span><small>Energy</small><strong><?=number_format((int)($liveResources['energy'] ?? 0))?></strong></span></div><div class="resource resource-dark"><em>DM</em><span><small>Dark Matter</small><strong><?=number_format((int)($liveResources['dark_matter'] ?? 0))?></strong></span></div><div class="resource resource-food"><em>F</em><span><small>Food</small><strong><?=number_format((int)($liveResources['food'] ?? 0))?></strong></span></div><div class="resource resource-water"><em>W</em><span><small>Water</small><strong><?=number_format((int)($liveResources['water'] ?? 0))?></strong></span></div><div class="resource resource-population"><em>POP</em><span><small>Population</small><strong><?=number_format((float)($liveResources['population'] ?? 150000), 2)?> / <?=number_format((float)($liveResources['population_capacity'] ?? 200000), 2)?></strong></span></div><span class="badge">TURN 84</span><span class="badge good">SERVER <?=htmlspecialchars($appMeta['server_status'])?></span><div class="account-menu"><button class="account-menu-toggle" type="button" aria-expanded="false" aria-controls="account-panel" onclick="toggleAccountMenu(event)"><span aria-hidden="true">⚙</span><span class="account-label">Account</span><strong>Tanang</strong></button><div id="account-panel" class="account-panel" role="menu" aria-label="Account options"><h3>Commander settings</h3><p>Authenticated account · session protected</p><button class="account-action" type="button" onclick="accountNavigate('account-info')">Account overview <span>→</span></button><button class="account-action" type="button" onclick="accountNavigate('resources')">Resources &amp; vault <span>→</span></button><button class="account-action" type="button" onclick="accountNavigate('race')">Race &amp; government <span>→</span></button><button class="account-action" type="button" onclick="accountRefresh()">Refresh live state <span>↻</span></button><label for="account-density">Display density<select id="account-density" onchange="setAccountDensity(this.value)"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label for="account-reduced-motion">Reduce motion<input id="account-reduced-motion" type="checkbox" onchange="setAccountMotion(this.checked)"></label><a class="account-action account-danger" role="menuitem" href="actions/logout.php">Sign out <span>↗</span></a><div class="account-meta">CSRF, RBAC, ownership, and transaction checks remain server-authoritative.</div></div></div></div></header><section class="content"><div class="heading"><div><div class="eyebrow" id="section">COMMAND CENTER</div><h1 id="title">Command Center</h1><p id="description">Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.</p></div></div><div id="content"></div></section><footer class="footer"><div><strong><?=htmlspecialchars($appMeta['name'])?></strong> <span>v<?=htmlspecialchars($appMeta['version'])?> · build <?=htmlspecialchars($appMeta['build'])?></span><div class="footer-developers">Developed by <?=htmlspecialchars($appMeta['developers']['lead'])?> · <?=htmlspecialchars($appMeta['developers']['team'])?></div></div><div class="footer-links"><a href="<?=htmlspecialchars($appMeta['legal']['rules'])?>">Rules</a><a href="<?=htmlspecialchars($appMeta['legal']['terms'])?>">Terms</a><a href="<?=htmlspecialchars($appMeta['legal']['privacy'])?>">Privacy</a><a href="<?=htmlspecialchars($appMeta['legal']['status'])?>">Status</a><span><?=htmlspecialchars($appMeta['copyright'])?></span></div></footer></main></div><script>
const registry=<?=$registryJson?>,details=<?=$pageDetailsJson?>,routeDetails=<?=$routeDetailsJson?>,interactions=<?=$interactionJson?>,pageContracts=<?=$pageContractsJson?>,state=<?=$stateJson?>,permissions=<?=$permissionJson?>;const nav=document.getElementById('nav');const requestedPage=new URLSearchParams(window.location.search).get('page')||'dashboard';let selected=Object.prototype.hasOwnProperty.call(routeDetails,requestedPage)?requestedPage:'dashboard';const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const fmt=n=>Number(n).toLocaleString();const fmtPopulation=n=>Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function toggleAccountMenu(event){if(event)event.stopPropagation();const panel=document.getElementById('account-panel');const toggle=document.querySelector('.account-menu-toggle');if(!panel)return;const open=panel.classList.toggle('open');if(toggle)toggle.setAttribute('aria-expanded',open?'true':'false')}function closeAccountMenu(){const panel=document.getElementById('account-panel');const toggle=document.querySelector('.account-menu-toggle');if(panel)panel.classList.remove('open');if(toggle)toggle.setAttribute('aria-expanded','false')}function accountNavigate(page){closeAccountMenu();selected=page;render();history.replaceState({},'', 'game.php?page='+encodeURIComponent(page))}function accountRefresh(){closeAccountMenu();window.location.reload()}function setAccountDensity(value){document.documentElement.dataset.density=value;localStorage.setItem('sgw_density',value)}function setAccountMotion(reduced){document.documentElement.dataset.reducedMotion=reduced?'true':'false';localStorage.setItem('sgw_reduced_motion',reduced?'true':'false')}function loadAccountPreferences(){const density=localStorage.getItem('sgw_density')||'comfortable';const reduced=localStorage.getItem('sgw_reduced_motion')==='true';document.documentElement.dataset.density=density;document.documentElement.dataset.reducedMotion=reduced?'true':'false';const densitySelect=document.getElementById('account-density');const motionToggle=document.getElementById('account-reduced-motion');if(densitySelect)densitySelect.value=density;if(motionToggle)motionToggle.checked=reduced;document.addEventListener('click',event=>{if(!event.target.closest('.account-menu'))closeAccountMenu()})}function flatten(){const out=[];Object.entries(registry).forEach(([groupKey,g])=>Object.entries(g.pages||{}).forEach(([key,p])=>out.push({groupKey,group:g.label||groupKey,key,...p})));return out}const all=flatten();
function renderNav(filter=''){nav.innerHTML='';Object.entries(registry).forEach(([groupKey,g])=>{const pages=Object.entries(g.pages||{}).filter(([key,p])=>{const hay=(key+' '+(p.title||'')+' '+(p.actions||[]).join(' ')+' '+(p.tables||[]).join(' ')).toLowerCase();return !filter||hay.includes(filter)});if(!pages.length)return;const d=document.createElement('details');d.open=true;const s=document.createElement('summary');s.textContent=(g.icon||'')+' '+(g.label||groupKey);d.appendChild(s);const sub=document.createElement('div');sub.className='sub';pages.forEach(([key,p])=>{const b=document.createElement('button');b.className='link'+(key===selected?' active':'');b.innerHTML='<span>'+esc(p.title)+'</span><small>'+esc(p.layout)+'</small>';b.onclick=()=>{selected=key;render()};sub.appendChild(b)});d.appendChild(sub);nav.appendChild(d)})}
function actionButton(key,label,cls=''){return permissions[key]?'<button class="button '+cls+' server-action" data-action="'+key+'">'+label+'</button>':'<button class="button" disabled>'+label+' (restricted)</button>'}
function commandCenter(){const c=state.colony;const progression=state.progression;const resourceTiles=Object.entries(state.resources).map(([key,value])=>'<div class="resource-tile"><small>'+esc(key.replace('_',' '))+'</small><strong>'+(key==='population'?fmtPopulation(value):fmt(value))+'</strong><div class="bar"><i style="width:'+Math.min(100,Math.max(10,Math.round(Number(value)/12400)))+'%"></i></div></div>').join('');const queues=state.queues.map(q=>'<div class="row"><div><strong>'+esc(q.name)+'</strong><small>'+esc(q.kind)+' · '+esc(q.level)+' · '+esc(q.status)+'</small></div><span class="badge">'+esc(q.remaining)+'</span></div>').join('');const missions=state.missions.map(m=>'<div class="row"><div><strong>'+esc(m.type)+'</strong><small>'+esc(m.target)+' · '+esc(m.status)+'</small></div><span class="badge">'+esc(m.eta)+'</span></div>').join('');const buildings=state.buildings.map(b=>'<tr><td>'+esc(b.name)+'</td><td>Level '+b.level+'</td><td>'+esc(b.output)+'</td><td><span class="badge good">'+esc(b.state)+'</span></td></tr>').join('');const alerts=state.alerts.map(a=>'<div class="alert"><strong class="'+esc(a.level)+'">'+esc(a.title)+'</strong><span>'+esc(a.detail)+'</span></div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Command Center';document.getElementById('description').textContent='Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.';document.getElementById('content').innerHTML='<div class="resource-strip">'+resourceTiles+'</div><div class="cc-grid"><div class="card wide"><div class="eyebrow">COLONY OVERVIEW</div><h2>'+esc(c.name)+' <span class="badge">'+esc(c.coordinate)+'</span></h2><div class="metric-grid"><div class="metric"><span>Population</span><strong>'+fmtPopulation(c.population)+' / '+fmtPopulation(c.capacity)+'</strong><small>Capacity utilization '+Math.round(c.population/c.capacity*100)+'%</small></div><div class="metric"><span>Morale</span><strong>'+c.morale+'%</strong><small>Stable colony confidence</small></div><div class="metric"><span>Life support</span><strong>'+fmt(c.food)+' / '+fmt(c.water)+'</strong><small>Food / Water reserves</small></div></div><div class="feedback" style="display:block">Live colony data synchronized successfully.</div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS</div><h2>Command controls</h2><div class="actions"><div class="action"><span>Process next turn</span>'+actionButton('process_turns','Process turns','dark')+'</div><div class="action"><span>Open target board</span>'+actionButton('choose_target','Choose target')+'</div><div class="action"><span>Read command reports</span>'+actionButton('review_reports','Review reports')+'</div></div><div class="permission">Authenticated commander · CSRF required · RBAC checked · ownership validated · transaction committed server-side.</div><div id="feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">CONSTRUCTION / RESEARCH / SHIPYARD</div><h2>Active queues</h2>'+queues+'</div><div class="card side-card"><div class="eyebrow">LIFE SUPPORT</div><h2>Colony systems</h2><div class="row"><div><strong>Food</strong><small>'+c.food_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Water</strong><small>'+c.water_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Morale</strong><small>Population stability</small></div><span class="badge good">'+c.morale+'%</span></div>'+actionButton('open_colony','Open colony')+'</div><div class="card wide"><div class="eyebrow">BUILDING STATUS</div><h2>Colony infrastructure</h2><table class="table"><thead><tr><th>Building</th><th>Level</th><th>Output</th><th>State</th></tr></thead><tbody>'+buildings+'</tbody></table></div><div class="card side-card"><div class="eyebrow">FLEET CONTROL</div><h2>Mission board</h2>'+missions+actionButton('dispatch_fleet','Dispatch fleet')+'</div><div class="card wide"><div class="eyebrow">UNIVERSAL PROGRESSION</div><h2>Tier '+progression.tier+' / Level '+progression.level+' <span class="badge">'+esc(progression.tier_name)+'</span></h2><div class="metric-grid"><div class="metric"><span>Global level</span><strong>'+progression.global_level+' / 483</strong><small>21 tiers × 23 levels</small></div><div class="metric"><span>Next level</span><strong>'+progression.next_level+'</strong><small>'+progression.progress_percent+'% progress</small></div><div class="metric"><span>Current effect</span><strong>+'+progression.effect_percent.toFixed(1)+'%</strong><small>Player progression modifier</small></div></div><div class="bar"><i style="width:'+progression.progress_percent+'%"></i></div><div class="actions" style="margin-top:12px">'+actionButton('progression_advance','Advance player level','dark')+' <span class="badge">Server validates cost, prerequisites, and tier cap</span></div></div><div class="card wide"><div class="eyebrow">COMMAND ALERTS</div><h2>Events and warnings</h2>'+alerts+'</div><div class="card side-card"><div class="eyebrow">COMMAND STATUS</div><h2>Colony systems synchronized</h2><p class="permission">Your colony commands are validated securely and your latest resources, queues, fleets, and progression are synchronized with the game server.</p><span class="badge good">LIVE STATE</span> <span class="badge">SERVER VERIFIED</span><details style="margin-top:14px"><summary>Technical details</summary><p class="permission">The browser submits player intent only. <code>process_turns</code> calls the PHP service layer, settles resources and queues in a transaction, writes an event, and returns refreshed state.</p><span class="badge">process_turns</span> <span class="badge">players</span> <span class="badge">player_resources</span> <span class="badge">rankings</span> <span class="badge">game_events</span></details></div></div>';document.querySelectorAll('.server-action').forEach(b=>b.onclick=()=>{const f=document.getElementById('feedback');f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → POST actions/game.php → permission check → transaction → refreshed dashboard state.'})}
function accountInfo(){const a=state.account||{commander:'Tanang',username:'tanang',race:"Tau'ri",government:'Stellar Republic',rank:'Commander',level:12,glory:1840,reputation:920,experience:72800,victories:38,defeats:7,protection:'Active',vacation:'Off',registration:'Complete',created:'2026-01-14',lastLogin:'Current session'};document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Account Information';document.getElementById('description').textContent='Commander identity, faction bonuses, progression, protection, and account security are read from authenticated server state.';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COMMANDER PROFILE</div><h2>'+esc(a.commander)+' <span class="badge good">AUTHENTICATED</span></h2><div class="metric-grid"><div class="metric"><span>Username</span><strong>'+esc(a.username)+'</strong><small>Account handle</small></div><div class="metric"><span>Rank</span><strong>'+esc(a.rank)+'</strong><small>Level '+fmt(a.level)+'</small></div><div class="metric"><span>Registration</span><strong>'+esc(a.registration)+'</strong><small>Created '+esc(a.created)+'</small></div></div></div><div class="card side-card"><div class="eyebrow">FACTION IDENTITY</div><h2>'+esc(a.race)+'</h2><div class="row"><div><strong>Government</strong><small>Current political system</small></div><span class="badge">'+esc(a.government)+'</span></div><div class="row"><div><strong>Combined modifiers</strong><small>Race × government</small></div><span class="badge good">APPLIED</span></div><button class="button dark" onclick="openPage(\'race\')">Review faction bonuses</button></div><div class="card wide"><div class="eyebrow">PROGRESSION</div><h2>Glory, Reputation, and experience</h2><div class="metric-grid"><div class="metric"><span>Experience</span><strong>'+fmt(a.experience)+'</strong><small>Level '+fmt(a.level)+' progression</small><div class="bar"><i style="width:72%"></i></div></div><div class="metric"><span>Glory</span><strong>'+fmt(a.glory)+'</strong><small>Ascension resource</small></div><div class="metric"><span>Reputation</span><strong>'+fmt(a.reputation)+'</strong><small>Diplomacy and rank</small></div></div><div class="row"><span>Victories / defeats</span><strong>'+fmt(a.victories)+' / '+fmt(a.defeats)+'</strong></div></div><div class="card side-card"><div class="eyebrow">PROTECTION</div><h2>Account safeguards</h2><div class="row"><div><strong>Protection status</strong><small>Combat eligibility</small></div><span class="badge good">'+esc(a.protection)+'</span></div><div class="row"><div><strong>Vacation mode</strong><small>Long-term protection</small></div><span class="badge">'+esc(a.vacation)+'</span></div><button class="button" onclick="openPage(\'vacation\')">Manage vacation mode</button></div><div class="card wide"><div class="eyebrow">SECURITY AND SESSION</div><h2>Authenticated account state</h2><div class="row"><span>Last login</span><strong>'+esc(a.lastLogin)+'</strong></div><div class="row"><span>Session protection</span><span class="badge good">CSRF + RBAC ENABLED</span></div><div class="row"><span>Data authority</span><span class="badge good">SERVER-SIDE PDO</span></div><p class="permission">Read-only account data is scoped to the authenticated commander. Race changes, government reform, vacation, and ascension use separate CSRF-protected PHP actions.</p></div><div class="card side-card"><div class="eyebrow">ACCOUNT CONTROLS</div><h2>Sub-pages</h2><div class="actions"><button class="button" onclick="openPage(\'race\')">Race and government</button><button class="button" onclick="openPage(\'ascension\')">Progression and ascension</button><button class="button" onclick="openPage(\'messages\')">Account messages</button></div><div class="feedback" style="display:block">State loaded from players, races, governments, rankings, progression, glory, protection, and audit records.</div></div></div>'}function openPage(page){selected=page;render()}function economyPage(){const b=interactions.economy.buttons||{};const r=state.resources;const banked=Number(r.banked_naquadah||0);const controlRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div>'+actionButton(x.action,label,'dark')+'</div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Resources & Vault';document.getElementById('description').textContent='Resources & Vault — Validated server-side state transition';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Resources & Vault</h2><div class="metric-grid"><div class="metric"><span>Available Naquadah</span><strong>'+fmt(r.naquadah)+'</strong><small>Spendable balance</small></div><div class="metric"><span>Protected vault</span><strong>'+fmt(banked)+'</strong><small>Banked Naquadah</small></div><div class="metric"><span>Dark Matter</span><strong>'+fmt(r.dark_matter)+'</strong><small>Special resource</small></div></div><div class="row"><span>Resource authority</span><span class="badge good">SERVER-VALIDATED</span></div><div class="row"><span>State transition</span><span class="badge">TRANSACTIONAL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+controlRows+'</div><p class="permission">authenticated commander</p></div><div class="card wide"><div class="eyebrow">RESOURCE RESERVES</div><h2>Eight-resource ledger</h2>'+Object.entries(r).map(([key,value])=>'<div class="row"><span>'+esc(key.replace('_',' '))+'</span><strong>'+fmt(value)+'</strong></div>').join('')+'</div><div class="card side-card"><div class="eyebrow">VAULT STATUS</div><h2>Resource transfers ready</h2><p class="permission">Deposit and withdraw Naquadah securely between your available balance and protected vault. The server checks every amount before committing the transfer.</p><span class="badge good">SERVER VERIFIED</span> <span class="badge">VAULT CONTROL ACTIVE</span><details style="margin-top:14px"><summary>Technical details</summary><p class="permission">Actions: <code>deposit</code> / <code>withdraw</code>.</p><span class="badge">player_resources</span> <span class="badge">game_settings</span><p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p><div style="margin-top:12px">'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></details></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}function breakdownPage(){const b=interactions.breakdown.buttons||{};const inc=state.income||{};const formula=inc.formula||'settlement = (base production × race modifier × government modifier × technology) − upkeep';const base=Number(inc.base_production||0),raceModifier=Number(inc.race_modifier||1),governmentModifier=Number(inc.government_modifier||1),technologyModifier=Number(inc.technology_modifier||1),foodUpkeep=Number((inc.upkeep||{}).food||0),waterUpkeep=Number((inc.upkeep||{}).water||0),energyUpkeep=Number((inc.upkeep||{}).energy||0),gross=Number(inc.gross_output||0),net=Number(inc.net_settlement||0),colonies=inc.colonies||[],primary=colonies[0]||null,stateLabel=inc.state||'empty';const actionRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div><button class="button income-intent" data-action="'+esc(x.action)+'">'+esc(label)+'</button></div>').join('');const states=['ready','empty','protected','error'];document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Income Breakdown';document.getElementById('description').textContent='Income Breakdown — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Income Breakdown</h2><div class="metric-grid"><div class="metric"><span>Base income</span><strong>'+fmt(base)+'</strong><small>Per settlement cycle</small></div><div class="metric"><span>Gross settlement</span><strong>'+fmt(gross)+'</strong><small>Before life-support upkeep</small></div><div class="metric"><span>Net settlement</span><strong>'+fmt(net)+'</strong><small>After food, water, and energy</small></div></div><div class="row"><div><strong>Settlement formula</strong><small>'+formula+'</small></div><span class="badge good">SERVER MODEL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+actionRows+'</div><p class="permission">Authenticated commander · read-only scope · owned colonies only</p><div id="income-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">MODIFIER BREAKDOWN</div><h2>Race, government, and technology</h2><div class="row"><span>Tau’ri race modifier</span><strong>+'+Math.round((raceModifier-1)*100)+'%</strong></div><div class="row"><span>Stellar Republic economy modifier</span><strong>+'+Math.round((governmentModifier-1)*100)+'%</strong></div><div class="row"><span>Technology multiplier</span><strong>'+technologyModifier.toFixed(2)+'×</strong></div><div class="row"><span>Combined production multiplier</span><strong>'+((raceModifier*governmentModifier*technologyModifier).toFixed(3))+'×</strong></div></div><div class="card side-card"><div class="eyebrow">COLONY PRODUCTION</div><h2>Owned colony comparison</h2><div class="row"><div><strong>'+esc(primary?primary.name:'No owned colonies')+'</strong><small>'+esc(primary?((primary.coordinate||'No coordinate')+' · '+(primary.biome||'Unknown biome')):'Commander-owned colony scope is empty')+'</small></div><span class="badge '+(primary?'good':'')+'">'+(primary?'PRIMARY':'EMPTY')+'</span></div><div class="row"><span>Population workforce</span><strong>'+fmt(primary?primary.population:0)+'</strong></div><div class="row"><span>Colony portfolio</span><strong>'+fmt(inc.colony_count||colonies.length)+'</strong></div><button class="button income-intent" data-action="read_colony_comparison">Compare colonies</button></div><div class="card wide"><div class="eyebrow">FOOD, WATER, AND ENERGY UPKEEP</div><h2>Life-support costs per settlement</h2><div class="metric-grid"><div class="metric"><span>Food upkeep</span><strong>'+fmt(foodUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Water upkeep</span><strong>'+fmt(waterUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Energy upkeep</span><strong>'+fmt(energyUpkeep)+'</strong><small>Infrastructure reserve</small></div></div><div class="row"><span>Total upkeep</span><strong>'+fmt(foodUpkeep+waterUpkeep+energyUpkeep)+'</strong></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read-only</p>'+['player_resources','player_colonies','races','government_types','technologies','universe_planets'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read actions are authenticated, CSRF-protected, RBAC-checked, and scoped to commander-owned colonies.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+states.map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.income-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('income-feedback');f.style.display='block';f.textContent='Read-only intent accepted: '+button.dataset.action+' → ownership check → EconomyService calculation → refreshed settlement state.'})}function sabotagePage(){const c=state.covert||{};const targets=state.target_board||[];const formula='damage = bounded system disruption × success probability × covert technology';const rows=targets.map(t=>'<tr><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.race)+'</td><td>#'+esc(t.rank)+'</td><td>'+fmt(t.defense)+'</td><td>'+fmt(t.covert)+'</td><td><span class="badge '+(t.status==='PROTECTED'?'':'good')+'">'+esc(t.status)+'</span></td><td><button class="button sabotage-intent" data-target="'+t.id+'" data-action="covert:sabotage" '+(t.status==='PROTECTED'?'disabled':'')+'>Sabotage</button></td></tr>').join('');const selected=targets.find(t=>t.status==='OPEN')||targets[0]||{id:0,name:'No target',covert:0,status:'PROTECTED'};const detection=Math.max(0,(Number(selected.covert)||0)-20-(Number(c.covert_level)||1));const success=Math.max(5,Math.min(95,100-detection));const damage=Math.max(1,Math.min(25,Math.round((Number(c.available_agents)||0)*0.10*(success/100)*(Number(c.covert_level)||1))));document.getElementById('section').textContent='ATTACK';document.getElementById('title').textContent='Sabotage Operations';document.getElementById('description').textContent='Target enemy systems with bounded sabotage damage and detection handling. '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>Sabotage mission</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>'+fmt(c.available_agents||0)+'</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+esc(formula.replace('damage = ','detection = defender counter-intelligence − attacker agents − covert technology; damage = '))+'</small></div><div class="metric"><span>Mission state</span><strong>'+esc(c.mission_state||'READY')+'</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2><div class="actions"><div class="action"><div><strong>Run reconnaissance</strong><small>Generate low-risk target intelligence with detection calculation.</small></div><button class="button sabotage-intent" data-action="covert:recon" data-target="'+selected.id+'">Run reconnaissance</button></div><div class="action"><div><strong>Run spy mission</strong><small>Resolve spy mission and store report.</small></div><button class="button sabotage-intent" data-action="covert:spy" data-target="'+selected.id+'">Run spy mission</button></div><div class="action"><div><strong>Run sabotage</strong><small>Resolve sabotage with detection and damage caps.</small></div><button class="button dark sabotage-intent" data-action="covert:sabotage" data-target="'+selected.id+'" '+(selected.status==='PROTECTED'?'disabled':'')+'>Run sabotage</button></div></div><p class="permission">Authenticated commander · agents required · target ownership validated</p><div id="sabotage-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">TARGET SYSTEMS</div><h2>Known enemy systems</h2><table class="table"><thead><tr><th>Realm</th><th>Race</th><th>Rank</th><th>Defense</th><th>Counter-intelligence</th><th>Status</th><th>Operation</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SABOTAGE PREVIEW</div><h2>Bounded damage model</h2><div class="metric-grid"><div class="metric"><span>Selected target</span><strong>'+esc(selected.name)+'</strong><small>'+esc(selected.status)+'</small></div><div class="metric"><span>Detection score</span><strong>'+fmt(detection)+'</strong><small>Defender covert − agents − technology</small></div><div class="metric"><span>Success probability</span><strong>'+fmt(success)+'%</strong><small>Clamped server-side</small></div><div class="metric"><span>Damage cap</span><strong>'+fmt(damage)+'</strong><small>Bounded system disruption</small></div></div><div class="row"><span>Formula</span><span class="badge good">'+esc(formula)+'</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">'+esc(formula)+'</p>'+['target_realms','players','player_resources','protection_states','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">All mutations require authentication, CSRF, RBAC, ownership, protection, resource, cooldown, and transaction checks.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.sabotage-intent').forEach(b=>b.onclick=()=>{const f=document.getElementById('sabotage-feedback');if(f){f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → target validation → detection and damage cap → CSRF/RBAC → transactional covert service.'}})}function reportsPage(){const reports=state.reports||[];const fallback=[{report_id:0,report_kind:'battle',title:'No battle reports yet',target_name:'Awaiting combat',action_type:'attack',turns_spent:0,loot:0,attacker_casualties:0,defender_casualties:0,report_text:'No battle report is available.',read_state:'READ',classification:'STANDARD'}];const rows=(reports.length?reports:fallback).map(r=>'<tr><td><strong>'+esc(r.title||r.target_name||'Report')+'</strong></td><td>'+esc(r.action_type||r.report_type||r.report_kind)+'