data-id="'+esc((reports[0]||{}).report_id||0)+'" data-action="message_read">Mark read</button></div><p class="permission">Recipient ownership and classification are checked server-side.</p><div id="reports-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">report visibility = recipient ownership + classification + read status</p>'+['target_realms','players','player_resources','protection_states','battles','battle_reports','covert_missions','intelligence_reports','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Report reads and read-state changes require authentication, CSRF, RBAC, recipient ownership, classification checks, and transactions.</p></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.report-intent').forEach(b=>b.onclick=()=>{const f=document.getElementById('reports-feedback');if(f){f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → recipient ownership → classification → read-state transaction.'}})}function weaponsPage(){const w=state.weapons||{};const owned=w.owned||[];const catalogue=w.catalogue||[];const formula='effective weapon power = base power × condition × technology modifier';const ownedRows=(owned.length?owned:[{name:'No weapons owned',category:'—',quantity:0,power:0,durability:0,max_durability:100,condition_percent:0,technology_modifier:1,effective_power:0,readiness:'UNAVAILABLE'}]).map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td><td>'+esc(x.category)+'</td><td>'+fmt(x.quantity)+'</td><td>'+fmt(x.durability)+' / '+fmt(x.max_durability)+'</td><td>'+fmt(x.condition_percent)+'%</td><td>'+fmt(x.effective_powe