}else{const type=mode==='spy'?'Spy mission':'Sabotage mission';body='<div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>'+type+'</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>160</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+map.formula+'</small></div><div class="metric"><span>Mission state</span><strong>READY</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2>'+Object.entries(contract.buttons||{}).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div><button class="button attack-intent" data-action="'+esc(x.action)+'">'+esc(label)+'</button></div>').join('')+'<p class="permission">Authenticated commander · agents required · target ownership validated</p></div>';}document.getElementById('content').innerHTML='<div class="cc-grid">'+body+'<div class="card side-card"><div class="eyebrow">COMBAT STATUS</div><h2>Combat operations ready</h2><p class="permission">Your selected combat operation is ready for server validation. Target protection, fleet readiness, resources, cooldowns, ownership, and deterministic battle resolution are checked before any mutation.</p><span class="badge good">SERVER VERIFIED</span> <span class="badge">TACTICAL CONTROL ACTIVE</span></div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p class="permission">'+map.formula+'</p>'+['target_realms','players','player_resources','protection_states','battles','battle_reports','covert_missions','intelligence_reports','game_events'].