ion system checks each level and returns only information your commander is allowed to see.</p><span class="badge good">SERVER VERIFIED</span> <span class="badge">DISCOVERY FILTER ACTIVE</span><details style="margin-top:14px"><summary>Technical details</summary><p class="permission">Action: <code>coordinate_lookup</code>. Parsing, hierarchy validation, discovery filtering, ownership classification, and navigation identifiers are server-authoritative.</p>'+['universe_galaxies','universe_sectors','universe_solar_systems','universe_planets','universe_discoveries','player_colonies'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'<div style="margin-top:12px">'+['ready','empty','error'].map(s=>'<div class="row"><span>'+s+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></details></div></div>';document.querySelectorAll('.coordinate-intent').forEach(b=>b.onclick=()=>{selected=b.dataset.route;render()})}
function planetBonusesPage(){const p=state.planet_bonuses||{},colonies=p.colonies||[],formula=p.formula||'planet bonus = biome modifier + building bonus + morale adjustment',applied=p.applied_formula||'applied production = base production × (1 + total bonus / 100)';const rows=colonies.length?colonies.map(c=>'<div class="row"><div><strong>'+esc(c.name||c.colony_name||'Colony')+'</strong><small>'+esc(c.biome||'Unknown biome')+' · morale '+Number(c.morale||0).toFixed(2)+'</small></div><span class="badge good">+'+fmt(c.total_bonus||c.bonus||0)+'%</span></div>').join(''):'<div class="empty"><strong>No colony bonuses available.</strong><p>Colonize or discover a settlement to see biome, building, and morale modifiers.</p></div>';document.getElementById('section').textContent='PLANETS';document.getElementById('title').textContent='Planet Bonuses';document.getElementById('description').textContent='Planet Bonuses — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PLANET PERFORMANCE</div><h2>Production modifiers</h2><p class="permission">Your colonies receive production effects from their biome, buildings, and morale. These modifiers are synchronized from the game server.</p><div class="metric-grid"><div class="metric"><span>Tracked colonies</span><strong>'+fmt(colonies.length)+'</strong><small>Commander-owned settlements</small></div><div class="metric"><span>Bonus model</span><strong>Biome + buildings</strong><small>Adjusted by colony morale</small></div><div class="metric"><span>Applied output</span><strong>Server calculated</strong><small>'+esc(applied)+'</small></div></div></div><div class="card side-card"><div class="eyebrow">BONUS STATUS</div><h2>Colony modifiers ready</h2><p class="permission">Review each colony’s production profile. No resource balance is changed by this read-only view.</p><span class="badge good">SERVER VERIFIED</span> <span class="badge">READ ONLY</span></div><div class="card wide"><div class="eyebrow">COLONY BONUSES</div><h2>Biome, buildings, and morale</h2>'+rows+'</div><div class="card wide"><div class="eyebrow">TECHNICAL DETAILS</div><h2>Read-only contract</h2><details open><summary>Backend contract and feedback states</summary><p class="permission">Action: <code>read-only</code>. Formula: <code>'+esc(formula)+'</code>. Applied formula: <code>'+esc(applied)+'</code>.</p>'+['planet_bonuses','player_colonies','universe_planets'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read access is authenticated, CSRF-protected, RBAC-checked, ownership-scoped, cooldown-aware, and server-authoritative. Writes are not performed by this panel.</p><div style="margin-top:12px">'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></details></div></div>'}function render(){const feedback=state.feedback||{};let banner=document.getElementById('global-feedback');if(!banner){banner=document.createElement('div');banner.id='global-feedback';banner.className='feedback';document.getElementById('content').before(banner)}banner.textContent=feedback.message||'';banner.dataset.state=feedback.state||'ready';banner.style.display=feedback.message?'block':'none';renderNav((document.getElementById('search').value||'').toLowerCase().trim());if(selected==='dashboard')commandCenter();else if(selected==='account-info')accountInfo();else if(selected==='resources')economyPage();else if(selected==='income')breakdownPage();else if(selected==='military-stats')militaryStatsPage();else if(selected==='sabotage')sabotagePage();else if(selected==='attack-log')reportsPage();else if(selected==='weapons')weaponsPage();else if(selected==='weapon-market')weaponMarketPage();else if(selected==='tech-defense')defenseTechnologyPage();else if(selected==='repair')weaponRepairPage();else if(selected==='units'||selected==='training')unitTrainingPage();else if(selected==='miners')workforcePage();else if(selected==='super-units')superUnitsPage();else if(selected==='unit-production')unitProductionPage();else if(selected==='technology')technologyTreePage();else if(selected==='tech-offense')offenseTechnologyPage();else if(selected==='tech-covert')covertTechnologyPage();else if(selected==='tech-anti-covert')antiCovertTechnologyPage();else if(selected==='spy-log')spyLogPage();else if(selected==='enemy-intelligence')enemyIntelligencePage();else if(selected==='race')racePage();else if(selected==='vacation')vacationPage();else if(selected==='ascension')ascensionPage();else if(selected==='galaxies')galaxyMapPage();else if(selected==='sectors')sectorMapPage();else if(selected==='solar-systems')solarSystemsPage();else if(selected==='universe-planets')universePlanetsPage();else if(selected==='moons')moonRegistryPage();else if(selected==='coordinates')coordinateSearchPage();else if(selected==='planet-bonuses')planetBonusesPage();else if(selected==='exploration')explorationPage();else if(['targets','spy'].includes(selected))attackPage(selected);else genericPage()};document.getElementById('search').oninput=()=>render();loadAccountPreferences();render();
</script></body></html>
